    </style>
</head>
<body>
    <div class="container">
        <h1>📅 교육 수강생 출석부</h1>
        <div class="stats">
            <span id="totalCount">전체: 3명</span>
            <span id="presentCount">출석: 2명</span>
        </div>
        <table>
            <thead><tr><th>이름</th><th>소속</th><th>출석 상태</th></tr></thead>
            <tbody id="studentList"></tbody>
        </table>
        <div id="msg" class="msg"></div>
    </div>

    <script>
        const students = [
            { id: 1, name: "김철수", dept: "기획과", present: true },
            { id: 2, name: "이영희", dept: "총무과", present: true },
            { id: 3, name: "박지민", dept: "홍보과", present: false }
        ];

        function render() {
            const list = document.getElementById('studentList');
            list.innerHTML = '';
            let presentCount = 0;
            students.forEach(s => {
                if (s.present) presentCount++;
                const tr = document.createElement('tr');
                tr.innerHTML = `
                    <td>${s.name}</td>
                    <td>${s.dept}</td>
                    <td><button class="status-btn ${s.present ? 'checked' : ''}" onclick="toggle(${s.id})">
                        ${s.present ? '✅ 출석' : '❌ 결석'}
                    </button></td>
                `;
                list.appendChild(tr);
            });
            document.getElementById('totalCount').innerText = `전체: ${students.length}명`;
            document.getElementById('presentCount').innerText = `출석: ${presentCount}명`;
        }

        window.toggle = (id) => {
            const s = students.find(x => x.id === id);
            s.present = !s.present;
            const msg = document.getElementById('msg');
            msg.style.display = 'block';
            msg.innerText = `${s.name}님의 상태가 변경되었습니다.`;
            msg.style.background = '#d4edda';
            render();
            setTimeout(() => msg.style.display = 'none', 2000);
        };

        render();
    </script>
</body>
</html>
