        .card { background: white; padding: 2rem; border-radius: 15px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); width: 100%; max-width: 400px; text-align: center; }
        h1 { color: #333; font-size: 1.5rem; margin-bottom: 1.5rem; }
        #roulette-box { width: 200px; height: 200px; border: 10px solid #4a90e2; border-radius: 50%; margin: 0 auto 20px; display: flex; align-items: center; justify-content: center; font-weight: bold; font-size: 1.2rem; color: #4a90e2; transition: all 0.3s; }
        input { width: 70%; padding: 10px; border: 1px solid #ddd; border-radius: 5px; margin-bottom: 10px; }
        button { padding: 10px 20px; background: #4a90e2; color: white; border: none; border-radius: 5px; cursor: pointer; }
        ul { list-style: none; padding: 0; margin-top: 20px; text-align: left; }
        li { background: #eee; margin: 5px 0; padding: 8px; border-radius: 4px; display: flex; justify-content: space-between; }
        #result-text { font-size: 1.5rem; font-weight: bold; color: #e67e22; margin: 20px 0; min-height: 2rem; }
    </style>
</head>
<body>
    <div class="card">
        <h1>팀 점심 메뉴 룰렛</h1>
        <div id="roulette-box">메뉴를 추가하세요!</div>
        <div id="result-text"></div>
        <input type="text" id="menuInput" placeholder="메뉴 이름 입력">
        <button onclick="addMenu()">추가</button>
        <button onclick="spin()" style="background: #27ae60;">돌리기!</button>
        <ul id="menuList"></ul>
    </div>

    <script>
        let menus = ["김치찌개", "돈까스", "쌀국수"];
        const listEl = document.getElementById('menuList');
        const boxEl = document.getElementById('roulette-box');
        const resultEl = document.getElementById('result-text');

        function render() {
            listEl.innerHTML = '';
            menus.forEach((m, i) => {
                const li = document.createElement('li');
                li.innerHTML = `${m} <span onclick="remove(${i})" style="cursor:pointer">❌</span>`;
                listEl.appendChild(li);
            });
        }

        function addMenu() {
            const input = document.getElementById('menuInput');
            if (input.value) {
                menus.push(input.value);
                input.value = '';
                render();
            }
        }

        function remove(idx) {
            menus.splice(idx, 1);
            render();
        }

        function spin() {
            if (menus.length === 0) return;
            resultEl.innerText = "돌아가는 중...";
            boxEl.style.transform = "rotate(360deg)";
            setTimeout(() => {
                const choice = menus[Math.floor(Math.random() * menus.length)];
                resultEl.innerText = `오늘의 메뉴는: ${choice}!`;
                boxEl.style.transform = "rotate(0deg)";
            }, 500);
        }
        render();
    </script>
</body>
</html>
